# Generated by tools/prepare_public_core.py; see CORE_PROVENANCE.json.


"""MVP monitoring scope and notification eligibility.

This module is deliberately independent from the PoC05 booking Rule Engine.
It decides whether an observed AVAILABLE slot is interesting enough to notify;
it never grants permission to book a facility.
"""

from calendar import monthrange
from dataclasses import dataclass
from datetime import date, datetime, timedelta
import json
from pathlib import Path

from .domain import FACILITY, HolidayCalendar, JST, Slot, iso_time, parse_date, require
from .domain import AVAILABILITY_MAX_AGE


BOOKING_POLICY = Path(__file__).with_name("data") / "katsushika_sports_booking_policy.json"
SCOPE_MODES = frozenset({"FIXED_DAYS", "CUSTOM", "ALL_BOOKABLE"})
MAX_SCOPE_DAYS = 366


def next_calendar_month_same_day(day: date) -> date:
    """Return the corresponding day next month, clamped to month end.

    The clamp is only a date-arithmetic rule.  ALL_BOOKABLE still requires a
    verified policy source and a successful DOM read through the resulting end
    date before a scan can be COMPLETE.
    """
    require(type(day) is date, "INVALID_DATE")
    year = day.year + (1 if day.month == 12 else 0)
    month = 1 if day.month == 12 else day.month + 1
    return date(year, month, min(day.day, monthrange(year, month)[1]))


@dataclass(frozen=True)
class MonitoringScope:
    mode: str = "ALL_BOOKABLE"
    days: int | None = None
    end_date: date | None = None

    def __post_init__(self):
        require(self.mode in SCOPE_MODES, "INVALID_MONITOR_SCOPE")
        if self.mode == "FIXED_DAYS":
            require(type(self.days) is int and 1 <= self.days <= MAX_SCOPE_DAYS
                    and self.end_date is None, "INVALID_MONITOR_SCOPE")
        elif self.mode == "CUSTOM":
            require(type(self.end_date) is date and self.days is None,
                    "INVALID_MONITOR_SCOPE")
        else:
            require(self.days is None and self.end_date is None,
                    "INVALID_MONITOR_SCOPE")

    def resolve(self, *, anchor: date, policy_path=BOOKING_POLICY):
        require(type(anchor) is date, "INVALID_DATE")
        policy = load_booking_policy(policy_path)
        require(FACILITY in policy["facilities"], "BOOKABLE_BOUNDARY_UNVERIFIED")
        bookable_end = next_calendar_month_same_day(anchor)
        # The published same-day rule does not specify the release of dates
        # 29/30/31 when the preceding month is shorter. Do not silently certify
        # a truncated full range on these ambiguous month-end dates.
        if (anchor.day == monthrange(anchor.year, anchor.month)[1]
                and anchor.day < monthrange(bookable_end.year, bookable_end.month)[1]
                and self.mode == "ALL_BOOKABLE"):
            require(False, "BOOKABLE_BOUNDARY_UNVERIFIED")
        if self.mode == "FIXED_DAYS":
            end = anchor + timedelta(days=self.days - 1)
            source = "ADMIN_FIXED_DAYS"
        elif self.mode == "CUSTOM":
            require(self.end_date >= anchor, "INVALID_MONITOR_SCOPE")
            end = self.end_date
            source = "ADMIN_CUSTOM_RANGE"
        else:
            end = bookable_end
            source = policy["policy_id"]
        count = (end - anchor).days + 1
        require(end <= bookable_end, "SCOPE_EXCEEDS_BOOKABLE_WINDOW")
        require(1 <= count <= MAX_SCOPE_DAYS, "INVALID_MONITOR_SCOPE")
        return ResolvedScope(self.mode, anchor, end, count, count * 14, source, True)


@dataclass(frozen=True)
class ResolvedScope:
    mode: str
    start_date: date
    end_date: date
    expected_days: int
    expected_slots: int
    boundary_source: str
    boundary_verified: bool

    def __post_init__(self):
        require(self.mode in SCOPE_MODES and type(self.start_date) is date
                and type(self.end_date) is date and self.start_date <= self.end_date,
                "INVALID_MONITOR_SCOPE")
        actual = (self.end_date - self.start_date).days + 1
        require(type(self.expected_days) is int and self.expected_days == actual
                and self.expected_slots == actual * 14
                and isinstance(self.boundary_source, str) and self.boundary_source
                and self.boundary_verified is True, "INVALID_MONITOR_SCOPE")


def load_booking_policy(path=BOOKING_POLICY):
    try:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        require(data["schema_version"] == "poc10-mvp-booking-policy-v1"
                and data["policy_id"] == "KATSUSHIKA_SPORTS_ONE_CALENDAR_MONTH_V1"
                and data["source_url"] == "https://www.city.katsushika.lg.jp/tourism/1002753/1030217/1003235.html"
                and data["rule"] == "ONE_CALENDAR_MONTH_SAME_DAY"
                and parse_date(data["verified_on"]) <= datetime.now(JST).date()
                and isinstance(data["facilities"], list)
                and all(isinstance(item, str) and item for item in data["facilities"]))
        return data
    except Exception:
        raise ValueError("BOOKABLE_BOUNDARY_UNVERIFIED") from None


def notification_eligibility(slot: Slot, calendar: HolidayCalendar, *, now: datetime,
                             read_status="COMPLETE", observed_at=None,
                             website_available=True):
    """Pure notification rule; no reservation/account/week-limit input exists."""
    require(isinstance(slot, Slot) and isinstance(calendar, HolidayCalendar),
            "INVALID_NOTIFICATION_INPUT")
    iso_time(now)
    now = now.astimezone(JST)
    if observed_at is not None:
        iso_time(observed_at)
    reasons = []
    eligible = False
    if slot.status != "AVAILABLE":
        reasons.append("SOURCE_NOT_AVAILABLE")
    elif read_status != "COMPLETE" or not website_available or observed_at is None:
        reasons.append("SOURCE_NOT_VERIFIED")
    elif not 0 <= (now - observed_at).total_seconds() <= AVAILABILITY_MAX_AGE.total_seconds():
        reasons.append("AVAILABILITY_DATA_STALE")
    elif slot.day < now.date() or (slot.day == now.date() and slot.start <= now.strftime("%H:%M")):
        reasons.append("PAST_OR_STARTED_SLOT")
    else:
        holiday = calendar.is_holiday(slot.day)
        weekend = slot.day.weekday() >= 5
        if not weekend and holiday is None:
            reasons.append("HOLIDAY_CALENDAR_UNVERIFIED")
        else:
            special = weekend or holiday is True
            allowed = {"16:00", "18:30", "20:30"} if special else {"20:30"}
            if slot.start in allowed:
                eligible = True
                reasons.append("MVP_NOTIFICATION_TIME_MATCH")
            else:
                reasons.append("OUTSIDE_NOTIFICATION_HOURS")
    return {
        "facility": FACILITY,
        "date": slot.day.isoformat(),
        "court": slot.court,
        "start": slot.start,
        "end": slot.end,
        "website_status": slot.status,
        "notification_eligibility": "ELIGIBLE" if eligible else (
            "DATA_INCOMPLETE" if any(code in reasons for code in {
                "SOURCE_NOT_VERIFIED", "AVAILABILITY_DATA_STALE", "HOLIDAY_CALENDAR_UNVERIFIED"
            }) else "NOT_ELIGIBLE"),
        "reason_codes": reasons,
        "execution_allowed": False,
        "auto_booking_allowed": False,
    }


